[CmdletBinding()]
param([string]$OutputPath)
$ErrorActionPreference='Stop';function To-WslPath([string]$Path){$full=[IO.Path]::GetFullPath($Path);if($full -notmatch '^([A-Za-z]):\\(.*)$'){throw "Unsupported Windows path: $full"};return "/mnt/$($Matches[1].ToLowerInvariant())/$($Matches[2].Replace('\','/'))"};$root=Split-Path -Parent $PSScriptRoot;$repoWsl=To-WslPath $root;$script="$repoWsl/Evals/isolation/wsl-sandbox.sh";$temp=Join-Path ([IO.Path]::GetTempPath()) ('agentic-isolation-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $temp|Out-Null;Set-Content -Encoding UTF8 -LiteralPath (Join-Path $temp 'VISIBLE.txt') -Value 'visible'
try{$workspaceWsl=To-WslPath $temp;$old=$ErrorActionPreference;$ErrorActionPreference='Continue';$out=wsl -d Ubuntu -- bash $script $workspaceWsl bash -lc 'test -f VISIBLE.txt; test ! -e /mnt/c; test ! -e Evals/fixtures/entity-parser/hidden/grade.py; printf "workspace_visible=yes\nwindows_mount_hidden=yes\nhidden_relative_unavailable=yes\n"' 2>&1|Out-String;$exit=$LASTEXITCODE;$ErrorActionPreference=$old}finally{if(Test-Path $temp){Remove-Item $temp -Recurse -Force}}
$result=[ordered]@{schema_version=1;run_at=[datetimeoffset]::Now.ToString('o');passed=($exit -eq 0 -and $out.Contains('workspace_visible=yes') -and $out.Contains('windows_mount_hidden=yes') -and $out.Contains('hidden_relative_unavailable=yes'));exit_code=$exit;evidence=$out;type='wsl-user-mount-namespace';windows_mount_hidden=$out.Contains('windows_mount_hidden=yes')}
if(-not $OutputPath){$OutputPath=Join-Path $root ("Evals/reports/{0}-wsl-isolation.json" -f (Get-Date -Format 'yyyy-MM-dd-HHmmss'))};$result|ConvertTo-Json -Depth 6|Set-Content -Encoding UTF8 $OutputPath;$result|ConvertTo-Json -Depth 6;if(-not $result.passed){exit 1}
